import {mountExperiment} from './experiment-ui.js';
import {R,C,T,B,fmt,stats,note,node,flow,table,bars,timeline,colors} from './computer-ui.js';
import * as M from './network-models.js';
const labs={};
const code=s=>`<pre class="nw-code"><code>${M.escapeHTML(s)}</code></pre>`;
const tiles=(values,label='')=>`<div class="nw-tiles" aria-label="${label}">${values.map(([text,state=''])=>`<span class="${state}">${text}</span>`).join('')}</div>`;
const verdict=(ok,text)=>`<div class="nw-verdict ${ok?'good':'bad'}" role="status">${text}</div>`;
const meters=items=>`<div class="nw-meters">${items.map(([label,value,max,color])=>`<div><span>${label}</span><div><i style="width:${Math.min(100,value/max*100)}%;background:${color}"></i></div><b>${value}</b></div>`).join('')}</div>`;

labs.packets=()=>({title:'Inspect a packet at each hop',state:{payload:400,hop:0},controls:[R('payload','Application payload bytes',100,1400,100),R('hop','Routers crossed',0,2)],render:s=>{
 const p=M.packet(s.payload,s.hop);return `<div class="nw-route">${['Laptop','Gateway','Transit','Server'].map((n,i)=>`<div class="${i===s.hop?'active':''}"><span>${n}</span><small>${i===s.hop?'frame leaving here':'network node'}</small></div>`).join('<b aria-hidden="true">→</b>')}</div><div class="nw-envelope"><small>LINK FRAME · ${p.frame} B · ${p.link}</small><div><small>IPv4 PACKET · ${p.ip} B · TTL ${p.ttl}</small><div><small>TCP SEGMENT · ${p.tcp} B · port 51000 → 443</small><div>Application bytes · ${p.payload} B</div></div></div></div>`+stats(['IP source',p.source],['IP destination',p.destination],['Frame overhead',`${p.frame-p.payload} B`])+note('Move across the path: the next-link frame changes and TTL decreases; source and destination IPs stay fixed in this example.');
},foot:'IPv4, TCP without options, Ethernet-like 14-byte header + 4-byte FCS. No VLAN, padding, preamble, inter-frame gap, TLS record overhead, NAT, or fragmentation. Addresses are documentation fixtures.'});

labs.routing=()=>({title:'Find the longest matching prefix',state:{destination:'10.42.7.19',specific:true},controls:[C('destination','Destination IPv4 address',['10.42.7.19','10.42.8.19','10.99.1.2','198.51.100.20']),T('specific','Install 10.42.7.0/24 route')],render:s=>{
 const r=M.routeFor(s.destination,s.specific);return `<div class="nw-route-table">${M.routes.filter(x=>s.specific||!x.prefix.endsWith('/24')).map(x=>`<div class="${x===r?'selected':''}"><code>${x.prefix}</code><span>→ ${x.next}</span><b>${x===r?'chosen':'—'}</b></div>`).join('')}</div>`+flow([['Destination',s.destination],['Forwarding decision',r.next,'blue']])+note('Remove the /24 while targeting 10.42.7.19. The covering /16 becomes the best installed match; the destination remains unchanged.');
},foot:'Fixed IPv4 forwarding table, one route per prefix, numeric longest-prefix matching. No administrative distance, equal-cost multipath, neighbor resolution, route learning, or packet filters.'});

labs.dns=()=>({title:'Publish an address; watch the cache age',state:{ttl:'60',now:0,cache:{address:'192.0.2.10',expires:60},authority:'192.0.2.10',answer:null,hit:null,lookups:0},controls:[C('ttl','TTL of answers (seconds)',['15','60','120']),B('publish','Publish new address'),B('advance','Advance 10 seconds'),B('query','Resolve name')],onChange:(s,k)=>{if(k==='ttl'){s.now=0;s.cache={address:'192.0.2.10',expires:+s.ttl};s.authority='192.0.2.10';s.answer=null;s.hit=null;s.lookups=0;}},actions:{publish:s=>{s.authority='192.0.2.20';},advance:s=>{s.now+=10;},query:s=>Object.assign(s,M.dnsLookup(s))},render:s=>{
 const fresh=s.now<s.cache.expires;return `<div class="nw-dns"><div>${node('Stub resolver','app.example')}</div><div class="${s.hit===true?'selected':''}">${node('Recursive cache',s.cache.address,'blue')}<small>${fresh?'Fresh':'Expired'} · ${Math.max(0,s.cache.expires-s.now)} s remain</small></div><div>${node('Root → TLD','Delegation referrals','purple')}${node('Authoritative answer',s.authority,'green')}</div></div>`+stats(['Clock',`${s.now} s`],['Last result',s.answer||'No query yet'],['Last query path',s.hit===null?'—':s.hit?'Cache hit':'Authoritative refresh'])+note('Publish the new address, resolve immediately, then advance past expiry and resolve again. Changing the TTL control starts a new scenario.');
},foot:'Single recursive answer cache, seeded at t=0. No serve-stale extension, negative cache, alias, resolver failure, or existing connection migration. Referrals illustrate a cold path; delegation caches are not timed.'});

labs.mtu=()=>({title:'Fit the narrowest path',state:{payload:1400,last:1280,tunnel:true,packetize:false},controls:[R('payload','UDP application payload (bytes)',100,1600,100),R('last','Final link IP MTU',1280,1500,20),T('tunnel','Tunnel consumes 80 bytes of a 1500-byte link'),T('packetize','Split application message into fitting datagrams')],render:s=>{
 const r=M.mtuModel(s.payload,s.last,s.tunnel,s.packetize);return meters(r.links.map((x,i)=>[['First link','Tunnel inner limit','Final link'][i],x,1500,colors[i]]))+`<div class="nw-packet-fit"><span style="width:${Math.min(100,r.size/1648*100)}%" class="${r.delivered?'good':'bad'}">Largest IP packet: ${r.size} B</span><i style="left:${r.mtu/1648*100}%" title="Path MTU ${r.mtu}"></i></div>`+stats(['Path MTU',`${r.mtu} B`],['Payload budget / datagram',`${r.maxPayload} B`],['Datagrams',r.chunks])+verdict(r.delivered,r.delivered?'Every packet fits this path':'Oversized packet cannot cross')+note('Splitting is done by the application here. The receiver would need message identifiers and reassembly; those costs are outside this size model.');
},foot:'IPv6 + UDP = 48 header bytes, no extension headers. Tunnel value is the inner IP budget. Assumes no loss for fitting packets; no source fragmentation or live PMTU discovery.'});

labs.delivery=()=>({title:'Deliver six pieces with one missing',state:{protocol:'TCP',lost:'2',step:0,arrived:[],repaired:false,message:'Advance arrivals, then repair the missing piece.'},controls:[C('protocol','Transport',['TCP','UDP']),C('lost','Piece lost on first transmission',['1','2','3','4','5','6']),B('next','Deliver next piece'),B('repair','Retransmit missing piece')],onChange:s=>{s.step=0;s.arrived=[];s.repaired=false;},actions:{next:s=>{if(s.step<6){s.step++;if(s.step!==+s.lost)s.arrived.push(s.step);s.message=`Piece ${s.step} ${s.step===+s.lost?'was lost':'arrived'}.`;}},repair:s=>{if(s.step===6&&!s.repaired){s.arrived.push(+s.lost);s.repaired=true;s.message=s.protocol==='UDP'?'Application explicitly retransmitted the datagram. UDP itself did not retry.':'The missing byte range arrived; buffered later bytes can become readable.';}else s.message='Deliver all six first transmissions before repair.';}},render:s=>{
 const r=M.delivery(s.arrived,s.protocol);return `<p class="small">Network arrival · outlined gap is not received</p>`+tiles(Array.from({length:6},(_,i)=>[i+1,s.arrived.includes(i+1)?'received':s.step>=i+1?'missing':'pending']))+`<p class="small">Application-visible ${s.protocol==='TCP'?'ordered ranges':'datagrams, in arrival order'}</p>`+tiles(r.visible.map(x=>[x,'ready']))+stats(['Visible pieces',r.visible.length],['Buffered behind gap',r.buffered.length],['Cumulative TCP ACK',s.protocol==='TCP'?r.ack:'Not supplied by UDP'])+note(s.message);
},foot:'Each piece is a 100-byte TCP range or one UDP datagram. TCP’s first data byte is numbered 1. One loss, no duplicates or timer algorithm; the repair button represents TCP recovery or an explicit UDP application retry.'});

labs.windows=()=>({title:'Find the remaining send credit',state:{cwnd:10,rwnd:6,inflight:4},controls:[R('cwnd','Congestion window (segments)',1,20),R('rwnd','Receive window (segments)',0,20),R('inflight','Segments already in flight',0,20)],render:s=>{
 const credit=M.sendBudget(s.cwnd,s.rwnd,s.inflight);return meters([['Network allowance',s.cwnd,20,colors[0]],['Receiver allowance',s.rwnd,20,colors[1]],['Already outstanding',s.inflight,20,colors[2]]])+`<div class="nw-formula">max(0, min(${s.cwnd}, ${s.rwnd}) − ${s.inflight}) = <b>${credit}</b></div>`+tiles(Array.from({length:20},(_,i)=>[i+1,i<s.inflight?'flight':i<s.inflight+credit?'ready':'pending']))+note(s.inflight>Math.min(s.cwnd,s.rwnd)?'The allowance is now below outstanding data. Stop sending new data; already-sent bytes cannot be recalled.':'The smaller window caps outstanding data; only unused credit is available.');
},foot:'Equal 1,000-byte segments; static snapshot of byte-based windows. No delayed ACK, window scaling, SACK, pacing, retransmission accounting, or sender buffer limit.'});

labs.congestion=()=>({title:'Grow the window, then back off',state:{cwnd:1,threshold:8,history:[1],round:0},controls:[B('ack','One fully acknowledged round'),B('loss','Congestion signal / halve window')],actions:{ack:s=>Object.assign(s,M.congestionStep(s)),loss:s=>Object.assign(s,M.congestionStep(s,true))},render:s=>{
 const max=Math.max(12,...s.history),points=s.history.map((n,i)=>`${35+i*560/Math.max(1,s.history.length-1)},${185-n/max*150}`).join(' ');return `<svg class="nw-chart" viewBox="0 0 640 220" role="img" aria-label="Last ${s.history.length} congestion windows in segments: ${s.history.join(', ')}"><path d="M35 20V185H610"/><polyline points="${points}"/>${s.history.map((n,i)=>`<circle cx="${35+i*560/Math.max(1,s.history.length-1)}" cy="${185-n/max*150}" r="4"/>`).join('')}<text x="40" y="210">Acknowledged rounds / congestion events →</text><text x="40" y="18">${max} segments</text></svg>`+stats(['Current window',s.cwnd],['Growth threshold',s.threshold],['Next successful growth',s.cwnd<s.threshold?'Up to 2×':'+1 segment'])+note('Advance three rounds to reach eight, then keep growing. Introduce a congestion signal and compare the recovery slope.');
},foot:'Round-based additive-increase / multiplicative-decrease teaching sketch, initial threshold 8, minimum window 1 and threshold 2. Last 16 samples shown. Not a complete Reno, CUBIC, or BBR implementation; no throughput estimate.'});

labs.connections=()=>({title:'Reuse a conversation instead of opening another',state:{requests:6,reuse:false,rtt:40},controls:[R('requests','Sequential requests',1,12),T('reuse','Reuse one connection'),R('rtt','Transport setup RTT (ms)',10,150,10)],render:s=>{
 const r=M.connectionLoad(s.requests,s.reuse,s.rtt);return `<div class="nw-connections">${Array.from({length:s.reuse?1:s.requests},(_,i)=>`<div><small>192.0.2.10:${51000+i}</small><span>↔</span><strong>198.51.100.20:443</strong><b>${s.reuse?s.requests:1} request${s.reuse&&s.requests>1?'s':''}</b></div>`).join('')}</div>`+stats(['TCP connections opened',r.opens],['Serialized TCP setup cost',`${r.handshakeMs} ms`],['Requests carried',s.requests])+note('The server port stays 443. Different client ports distinguish these connections; pooling keeps a useful conversation open.');
},foot:'Sequential requests, one-RTT TCP setup, all connections healthy. Counts only transport setup: TLS, body transfer, idle timeout, close/TIME_WAIT, NAT mappings, and concurrency are discussed separately.'});

labs.handshakes=()=>({title:'Count waits before the first response byte',state:{protocol:'HTTP/2',reused:false,rtt:60},controls:[C('protocol','HTTPS stack',['HTTP/2','HTTP/3']),T('reused','Use an already established connection'),R('rtt','Round-trip time (ms)',10,200,10)],render:s=>{
 const r=M.handshake(s.protocol,s.reused,s.rtt);return timeline(r.rows.map((row,i)=>[...row,colors[i]]),Math.max(1,r.firstByte))+stats(['Setup round trips',r.setup],['Time to first byte',`${r.firstByte} ms`],['Request round trip',`${s.rtt} ms`])+note('Increase distance by raising RTT. Every remaining sequential handshake round amplifies the cost. Reuse and a fresh resumed connection are different states.');
},foot:'DNS resolved; ordinary TCP + TLS 1.3 costs two setup RTTs, QUIC + TLS one. No Retry, loss, 0-RTT, server processing, certificate transfer size, protocol discovery, or TCP Fast Open. Illustrative client-observed first byte.'});

labs.multiplexing=()=>({title:'Lose A’s first packet; inspect stream B',state:{protocol:'HTTP/2',lost:1,repaired:false},controls:[C('protocol','HTTP transport',['HTTP/2','HTTP/3']),R('lost','Missing packet position',1,6),T('repaired','Lost data has been retransmitted successfully')],render:s=>{
 const packets=M.multiplex(s.protocol,s.lost,s.repaired);return `<p class="small">Sent order · each packet contains one frame</p>`+tiles(packets.map(p=>[p.stream+p.part,!p.arrived?'missing':p.ready?'ready':'held']))+`<div class="nw-streams">${['A','B'].map(stream=>`<div><h3>Stream ${stream}</h3>${tiles(packets.filter(p=>p.stream===stream).map(p=>[p.stream+p.part,!p.arrived?'missing':p.ready?'ready':'held']))}<small>${packets.filter(p=>p.stream===stream&&p.ready).length} frames available to stream</small></div>`).join('')}</div>`+`<div class="nw-key"><span>✓ green: available</span><span>amber: received, held</span><span>dashed: missing</span></div>`+note('Compare protocols with packet 1 missing. QUIC can deliver received B frames while stream A waits; TCP’s ordered byte stream holds later B bytes too.');
},foot:'All other packets have arrived; one frame per packet, independent response bodies, headers already decoded. No flow-control limit, QPACK dependency, shared congestion slowdown, or application-level dependency.'});

labs.methods=()=>({title:'Repeat an operation after an uncertain result',state:{method:'POST',repeats:0},controls:[C('method','Operation',['GET','PUT','POST']),B('send','Send / retry the operation')],onChange:s=>{s.repeats=0;},actions:{send:s=>{s.repeats=Math.min(12,s.repeats+1);}},render:s=>{
 const r=M.methodEffect(s.method,s.repeats),value=s.repeats?r.value:0;return code(s.method==='GET'?'GET /counter → read current value':s.method==='PUT'?'PUT /counter  { value: 7 }':'POST /entries  { append: 1 }')+flow([['Applications',s.repeats],['Resulting value',value,'blue']])+tiles(Array.from({length:value},(_,i)=>[i+1,'ready']))+stats(['Safe method',r.safe?'Yes':'No'],['Idempotent fixture',r.idempotent?'Yes':'No'])+note('Each click is applied by the server. A caller could retry because a prior response was lost; the effect depends on the operation contract.');
},foot:'Initial value 0; GET reads it, PUT replaces with 7, POST appends one entry. Independent fixtures reset on method change. No actual HTTP request, request deduplication, or concurrent writer.'});

labs.conditions=()=>({title:'Compare the client’s validator with the current version',state:{mode:'Read',matches:true},controls:[C('mode','Conditional operation',['Read','Write']),T('matches','Client’s v1 validator still matches server')],render:s=>{
 const r=M.conditional(s.mode,s.matches);return flow([['Client copy','v1'],['Server current',s.matches?'v1':'v2','blue']])+code(s.mode==='Read'?'GET /document\nIf-None-Match: "v1"':'PUT /document\nIf-Match: "v1"\n\n{ updated document }')+stats(['HTTP status',r.status],['Response body',`${r.body} kB`],['Write applied',s.mode==='Write'?s.matches?'Yes':'No':'Read only'])+note(s.mode==='Read'?(s.matches?'304 reuses the cached body; response headers still travel.':'200 carries the current representation to replace the stale copy.'):(s.matches?'The version precondition permits this atomic write.':'412 rejects the stale write before mutation.'),s.mode==='Write'&&!s.matches);
},foot:'Single strong opaque ETag, full 120 kB GET body, authorized requests, atomic server comparison/write. PUT returns an empty 200 response in this fixture. No weak validators, range requests, or cache freshness bypass.'});

labs.proxies=()=>({title:'Trace the identity across a terminating proxy',state:{claim:true,trust:false},controls:[T('claim','Client supplies a forged forwarding header'),T('trust','Origin uses only metadata normalized by its trusted edge')],render:s=>{
 const identity=M.proxyIdentity(s.claim,s.trust);return `<div class="nw-proxy">${node('Browser','198.51.100.27')}<span>TLS connection 1</span>${node('Edge proxy','192.0.2.5','blue')}<span>TLS connection 2</span>${node('Origin','Private service','purple')}</div>`+code(s.claim?'Incoming claim: Forwarded: for=203.0.113.99':'No client-supplied forwarding claim')+stats(['Origin socket peer','192.0.2.5'],['Selected client identity',identity],['Trust policy',s.trust?'Sanitized edge chain':'Unvalidated header / peer'])+note(s.trust?'The edge discards caller-supplied forwarding claims and writes its verified peer address. The origin accepts traffic only through that edge.':s.claim?'The origin trusts arbitrary input and attributes this request to the forged address.':'Without a forwarding policy, the origin sees the proxy’s address, not the browser’s.',!s.trust);
},foot:'Two independent encrypted connections, one known trusted edge, no bypass when trusted mode is enabled. A simplified attribution decision, not a Forwarded parser or authorization system.'});

labs.balancing=()=>({title:'Distribute counts or queued work',state:{jobs:12,policy:'Round robin',exclude:false},controls:[R('jobs','Simultaneous jobs',1,18),C('policy','Assignment policy',['Round robin','Shortest queued work']),T('exclude','Remove slow worker from new assignments')],render:s=>{
 const r=M.balance(s.jobs,s.policy,s.exclude);return `<div class="nw-workers">${r.counts.map((n,i)=>`<div><h3>Worker ${'ABC'[i]} · ${i===2?'4':'1'} s/job</h3><div>${Array.from({length:n},()=>`<i style="width:${i===2?52:13}px" title="${i===2?4:1} seconds"></i>`).join('')}</div><small>${n} jobs · finishes at ${r.finish[i]} s</small></div>`).join('')}</div>`+stats(['All jobs finish',`${r.total} s`],['Jobs assigned',r.counts.reduce((a,b)=>a+b,0)],['Workers eligible',s.exclude?2:3])+note('Equal tile counts need not mean equal queue duration. Width represents service time; the alternative policy uses perfectly known remaining work.');
},foot:'Batch arrives at t=0; serial FIFO worker queues, fixed 1/1/4-second jobs, no network cost. Shortest queued work is an oracle teaching policy, not a claim about a particular load balancer. Exclusion rebuilds the whole scenario.'});

labs.freshness=()=>({title:'Ask the cache whether it can reuse a response',state:{age:30,maxAge:60,policy:'max-age',changed:false,shared:true},controls:[R('age','Current response age (seconds)',0,120,5),R('maxAge','Freshness lifetime (seconds)',10,120,10),C('policy','Cache-Control policy',['max-age','no-cache','no-store','private']),T('changed','Origin representation changed'),T('shared','Inspect shared edge cache, not browser cache')],render:s=>{
 const r=M.cacheDecision(s);return `<div class="nw-age"><div style="width:${Math.min(100,s.age/120*100)}%"></div><i style="left:${s.maxAge/120*100}%"></i><span>Age ${s.age}s · freshness boundary ${s.maxAge}s</span></div>`+flow([['Storage permission',r.stored?'May store':'Do not store'],['Next request',r.action,'blue']])+stats(['Network exchange',r.network?'Required':'None'],['Response body transferred',`${r.bytes} kB`],['Locally fresh',r.fresh?'Yes':'No'])+note('A fresh cached response can still differ from the current origin. Freshness is permission to reuse under a policy, not knowledge that the origin has not changed.');
},foot:'Authorized cacheable GET, strong ETag, successful origin access, 120 kB body; headers excluded. private is combined with selected max-age. No s-maxage, heuristic freshness, stale allowances, validation failure, or cache eviction.'});

labs.variants=()=>({title:'Include the representation’s selecting dimensions',state:{encoding:'identity',vary:false,privateResponse:false,shared:true},controls:[C('encoding','New request Accept-Encoding',['identity','br']),T('vary','Response declares Vary: Accept-Encoding'),T('privateResponse','Response is marked private'),T('shared','Use a shared cache')],render:s=>{
 const r=M.variant(s.encoding,s.vary,s.privateResponse,s.shared);return `<div class="nw-cache-keys"><div><small>Previous request</small><strong>/report · br</strong><span>Stored representation: Brotli</span></div><div class="${r.mismatch?'bad':'good'}"><small>New lookup key</small><strong>${r.key}</strong><span>${!r.usable?'Shared reuse prohibited':r.mismatch?'WRONG: br for identity client':'Matching variant selected'}</span></div></div>`+stats(['Shared reuse permitted',r.usable?'Yes':'No'],['Response selection',r.served])+note(r.mismatch?'A missing key dimension merges incompatible requests. Enabling Vary separates their representations.':'The fixture assumes a matching variant is available or fetched when its key is distinct.',r.mismatch);
},foot:'Seeded Brotli response; with Vary, both identity and br variants are available. Without Vary, URL-only key reuses br. private blocks shared reuse. No real compression, cookies, authorization, or CDN-specific key configuration.'});

labs.origins=()=>({title:'Change the origin, then follow the fetch gates',state:{target:'https://app.example/other',preflight:true,allow:false},controls:[C('target','Request URL',['https://app.example/other','https://api.example/data','http://app.example/data','https://app.example:8443/data']),T('preflight','Request requires a successful preflight'),T('allow','Server grants this origin, method, and headers')],render:s=>{
 const r=M.originResult(s.target,s.preflight,s.allow),u=new URL(s.target),mixed=u.protocol==='http:';
 return `<div class="nw-origin"><span>scheme<b>${u.protocol}</b></span><span>host<b>${u.hostname}</b></span><span>effective port<b>${u.port||(u.protocol==='https:'?'443':'80')}</b></span></div>`+flow([['Page origin','https://app.example'],['Origin comparison',r.same?'Same origin':'Cross origin','blue'],['Actual request',mixed?'Blocked mixed content':r.sent?'Sent':'Preflight blocks it','purple'],['JS response access',!mixed&&r.sent&&r.readable?'Allowed':'Unavailable']])+note(mixed?'An HTTPS page’s active HTTP fetch is blocked as mixed content before CORS can grant access.':!r.same&&!s.preflight&&!s.allow?'This simple request is sent, but the response is hidden from JavaScript.':'A grant must cover the requesting origin and this request’s actual method and headers.');
},foot:'Fetch from https://app.example, no credentials, no redirects. The allow toggle covers both preflight and response grants. Mixed active HTTP content is blocked. No preflight cache, CSP, private-network policy, or browser extensions.'});

labs.rendering=()=>({title:'Follow the browser’s dependency timeline',state:{css:60,js:180,defer:false},controls:[R('css','Stylesheet fetch duration (ms)',20,240,20),R('js','Script fetch duration (ms)',20,240,20),T('defer','Use a deferred classic script')],render:s=>{
 const r=M.renderPath(s.css,s.js,s.defer),end=Math.max(r.ready,r.paint)+20;return timeline(r.rows.map((row,i)=>[...row,colors[i%colors.length]]),end)+stats(['HTML parsing complete',`${r.domReady} ms`],['First paint opportunity',`${r.paint} ms`],['Script and DOM ready',`${r.ready} ms`])+note('Both resources are discovered at 20 ms. Defer lets the remaining HTML parse while the script downloads; a stylesheet can still delay script execution and paint.');
},foot:'HTML parse CPU 40 ms, script CPU 30 ms, no other work. Parallel independent fetches; blocking script waits for prior CSS. A modeled paint opportunity, not measured browser scheduling, DCL, LCP, or interactivity. No async/module scripts, images, fonts, layout cost, or preload scanner.'});

labs['main-thread']=()=>({title:'Give input a gap between tasks',state:{chunks:1},controls:[R('chunks','Split 120 ms of CPU into tasks',1,12)],render:s=>{
 const r=M.mainThread(s.chunks);return timeline([...r.rows.map(row=>[...row,colors[2]]),['Input handled',r.input,2,colors[1]]],Math.max(160,r.total+10))+stats(['Input arrives', '25 ms'],['Input waiting',`${fmt(r.delay)} ms`],['CPU work completes',`${fmt(r.total)} ms`])+note('More tasks preserve 120 ms of work but create opportunities to service input. The modeled scheduling gaps add elapsed time.');
},foot:'Deterministic 5 ms gaps between ordinary tasks, input handled at the first available gap or idle time, negligible handler cost. No microtask chains, rendering competition, worker threads, or browser-specific input priority.'});

labs.offline=()=>({title:'Serve v1 locally while v2 is live',state:{strategy:'Cache first',online:true,version:'v1',cached:'v1',shown:null,network:null},controls:[C('strategy','Service-worker strategy',['Cache first','Network first']),T('online','Network is available'),B('publish','Publish origin v2'),B('load','Load page'),B('clear','Clear this local cache entry')],actions:{publish:s=>{s.version='v2';},load:s=>{const r=M.workerCache(s.strategy,s.online,s.version,s.cached);s.shown=r.shown;s.network=r.network;s.cached=r.updated;},clear:s=>{s.cached=null;}},render:s=>flow([['Origin version',s.version],['Local Cache Storage',s.cached||'Empty','purple'],['Last load',s.network===null?'Not attempted':s.shown||'Unavailable','blue']])+stats(['Last load used network',s.network===null?'—':s.network?'Attempted':'No'],['Strategy',s.strategy])+note('Publish v2 and load with cache-first. Then use network-first online, load again, and try offline. Control changes apply to the next load.'),foot:'Pure simulation; no service worker is registered and no browser caches are modified. Existing active worker, cache-on-success, immediate network result, offline fallback. No activation race, timeout, HTTP cache, eviction, or multi-asset consistency.'});

labs.redirects=()=>({title:'Follow the method across a redirect',state:{status:'303',method:'POST',hops:1,rtt:60},controls:[C('status','Redirect status',['303','307']),C('method','Original method',['POST','GET']),R('hops','Redirect exchanges before final request',1,5),R('rtt','RTT per redirect exchange (ms)',10,150,10)],render:s=>{
 const r=M.redirectResult(s.status,s.method,s.hops,s.rtt);return `<div class="nw-redirects">${node('Initial request',s.method)}${Array.from({length:s.hops},(_,i)=>`<span class="op">→</span>${node('Redirect '+(i+1),s.status,'purple')}`).join('')}<span class="op">→</span>${node('Final request',r.method,'blue')}</div>`+stats(['Extra waiting before final exchange',`${r.extra} ms`],['POST body preserved',r.bodyRetained?'Yes':'No'])+note(s.status==='303'?'This POST’s follow-up becomes a GET. More 303 hops keep it a GET.':'307 preserves the method and body. Do not accidentally redirect a mutation to an unintended target.');
},foot:'All redirects same selected status, negligible processing, established connections, no loops or cache. Counts only extra redirect RTTs; final exchange and cross-origin DNS/TLS costs excluded. POST body is a symbolic fixture.'});

labs.compression=()=>({title:'Trade network bytes against CPU time',state:{kb:200,ratio:30,mbps:20,cpu:15},controls:[R('kb','Original body (decimal kB)',20,1000,20),R('ratio','Encoded size (% of original)',10,100,5),R('mbps','Link rate (Mb/s)',1,100),R('cpu','Extra encode + decode work (ms)',0,100,5)],render:s=>{
 const r=M.compression(s.kb,s.ratio,s.mbps,s.cpu);return bars([['Uncompressed transfer',r.raw,colors[1]],['Encoded transfer',r.compressed,colors[0]],['Encoding + decoding',r.cpu,colors[2]],['Encoded total',r.total,'#e6a79a']])+stats(['Bytes transferred',`${fmt(s.kb*s.ratio/100)} kB`],['Net time saved',`${fmt(r.saved)} ms`])+note(r.saved>0?'Byte savings outweigh the modeled CPU cost.':'The CPU cost equals or exceeds transfer savings on this link.',r.saved<0);
},foot:'Decimal units; 1 kB = 1,000 bytes. Single serial transfer, encode/decode costs combined, no overlap, RTT, cache, compression dictionary, or CPU contention. Ratios and CPU are independently chosen illustrative inputs.'});

labs.realtime=()=>({title:'Deliver five changes over twenty seconds',state:{mode:'Polling',interval:'5'},controls:[C('mode','Delivery pattern',['Polling','SSE','WebSocket']),C('interval','Polling interval (seconds)',['1','2','5','10'])],render:s=>{
 const r=M.realtime(s.mode,+s.interval);return `<div class="nw-events"><div><span>Event created</span>${M.eventTimes.map(t=>`<i style="left:${t/20*100}%" title="${t}s"><b>${t}</b></i>`).join('')}</div><div><span>Delivered</span>${r.deliveries.map((t,i)=>`<i style="left:${t/20*100}%;top:${15+(r.deliveries.slice(0,i).filter(x=>x===t).length*12)}px" title="Event ${i+1} delivered at ${t}s"></i>`).join('')}</div><p class="small">0 → 20 seconds · stacked marks are events delivered together</p></div>`+stats(['Mean discovery delay',`${fmt(r.average)} s`],['Requests / channel setups',r.requests],['Client can push on this channel',r.bidirectional?'Yes':'No'])+note('Polling waits for the next scheduled request. SSE and WebSocket send immediately in this zero-network-delay fixture; they still need application recovery after a disconnect.');
},foot:'Events at 1, 4, 9, 13, 19 seconds. Polls start after one interval and end at 20; streaming setup completed at t=0. No headers, network delay, loss, heartbeats, or reconnect. Interval affects polling only.'});

labs.backpressure=()=>({title:'Keep the consumer queue bounded',state:{produce:8,consume:2,capacity:12,backpressure:false,queue:0,produced:0,consumed:0,tick:0,paused:0},controls:[R('produce','Producer offer (chunks/tick)',1,10),R('consume','Consumer capacity (chunks/tick)',1,10),T('backpressure','Pause production when 12-chunk buffer fills'),B('tick','Advance one tick')],actions:{tick:s=>{if(s.tick<100)Object.assign(s,M.queueStep(s));}},render:s=>{
 return flow([['Producer',`${s.produce} offered / tick`],['Buffer',`${s.queue} chunks`,'purple'],['Consumer',`${s.consume} max / tick`,'blue']])+tiles(Array.from({length:Math.min(36,s.queue)},(_,i)=>[i+1,i<12?'held':'overflow']))+(s.queue>36?`<p class="small">+ ${s.queue-36} chunks not drawn</p>`:'')+stats(['Produced / consumed',`${s.produced} / ${s.consumed}`],['Paused this tick',s.paused],['Ticks',s.tick])+note(s.queue>12?'The backlog exceeds the intended buffer. Pausing production must propagate upstream; it cannot erase already queued chunks.':'Consumption happens first each tick, then available buffer space permits production.',s.queue>12);
},foot:'Equal chunks, empty initial queue, fixed 12-chunk capacity when backpressure is enabled, 100-tick cap. Turning it on with an existing excess drains that excess before new production. No dropping, disk spill, or upstream queue is modeled.'});

labs.waterfall=()=>({title:'Separate setup, waiting, and transfer',state:{rtt:60,dns:30,reuse:false,server:40,body:80},controls:[R('rtt','Network RTT (ms)',10,200,10),R('dns','DNS lookup (ms)',0,150,10),T('reuse','Connection already established'),R('server','Server work (ms)',0,300,10),R('body','Response body transfer (ms)',10,400,10)],render:s=>{
 const r=M.waterfall(s);return timeline(r.rows.map((row,i)=>[...row,colors[i]]),r.total)+stats(['Lookup → first byte',`${r.ttfb} ms`],['Request → first byte',`${s.rtt+s.server} ms`],['Response complete',`${r.total} ms`])+note('This starts with an explicit DNS lookup even when connection reuse is selected; set DNS to zero for a typical fully warm request. Change one stage to see which interval moves.');
},foot:'Sequential synthetic waterfall, TLS 1.3 on TCP, no overlap, redirects, loss, queueing, browser parsing, or cache. Server duration excludes propagation; body duration is separate. No actual request is sent.'});

labs.throughput=()=>({title:'Fill the bandwidth-delay product',state:{mbps:100,rtt:80,window:64,size:10},controls:[R('mbps','Link capacity (Mb/s)',10,1000,10),R('rtt','RTT (ms)',10,200,10),R('window','Effective in-flight limit (decimal kB)',16,2048,16),R('size','Body size (decimal MB)',1,100)],render:s=>{
 const r=M.transfer(s.mbps,s.rtt,s.window,s.size);return bars([['Link capacity (Mb/s)',s.mbps,colors[1]],['Window / RTT (Mb/s)',r.windowMbps,colors[0]],['Steady-state ceiling (Mb/s)',r.rate,colors[2]]])+stats(['Full-link bytes in flight',`${fmt(r.bdpKB)} kB`],['Ideal body duration',`${fmt(r.seconds,2)} s`],['Limiting factor',r.windowMbps<s.mbps?'Window / RTT':'Link capacity'])+note('At a fixed window, longer RTT returns sending credit more slowly. Increasing bandwidth helps only after that window permits enough outstanding data.');
},foot:'Steady-state ceiling = min(link bits/s, window bytes × 8 / RTT seconds). Decimal kB/MB, no handshake, slow start, loss, headers, competing traffic, or CPU. A lower bound on body duration under these assumptions.'});

labs.timeouts=()=>({title:'Separate inactivity from total lifetime',state:{first:40,chunks:5,gap:40,idle:60,total:250},controls:[R('first','Request → first chunk (ms)',10,150,10),R('chunks','Number of response chunks',1,10),R('gap','Gap between chunks (ms)',10,150,10),R('idle','Read idle timeout (ms)',20,200,10),R('total','Total deadline from start (ms)',50,600,10)],render:s=>{
 const r=M.deadline(20,s.first,s.chunks,s.gap,s.idle,s.total);return `<div class="nw-deadline"><div class="nw-deadline-track">${r.arrivals.map((t,i)=>`<span style="left:${t/Math.max(r.completion,s.total)*100}%" class="${t<r.at||!r.timeout?'ready':'pending'}" title="Chunk ${i+1} at ${t}ms">${i+1}</span>`).join('')}<i style="left:${r.at/Math.max(r.completion,s.total)*100}%" title="Stops at ${r.at}ms"></i></div><p class="small">Response chunk schedule · vertical line is operation stop</p></div>`+stats(['Operation result',r.reason],['Stops at',`${r.at} ms`],['Full response would finish',`${r.completion} ms`])+note(r.timeout?'Only chunks arriving before the timeout are observed. A timed-out client does not imply remote work stopped or a mutation was undone.':'Both the initial wait and later gaps fit the idle budget, and completion precedes the total deadline.',r.timeout);
},foot:'Connect always succeeds in 20 ms; read-idle clock starts then and resets at each chunk. Total deadline includes connect. At an exact deadline boundary, expiry wins. No separate connect timer, retries, cancellation propagation, or real timers.'});

const incidents=[
 ['Only cold requests are slow','Inspect DNS and connection phases','Cold: 280 ms setup + 35 ms request. Reused: 0 ms setup + 35 ms request.'],
 ['Deploy succeeded; some clients see old HTML','Inspect serving cache and response age','Origin returns v2. Edge hit returns v1 with Age: 40 and max-age=60.'],
 ['Tiny requests pass; large datagrams vanish','Inspect path MTU and discovery signals','The same destination receives 900-byte IP packets but not 1,450-byte packets after a tunnel change.'],
 ['Bytes arrived; clicks still wait','Inspect main-thread tasks','Response finishes at 100 ms. A 200 ms JavaScript task begins at 110 ms; a click arrives at 150 ms.']
];
labs.investigation=()=>({title:'Pick a measurement that separates explanations',state:{incident:incidents[0][0],measure:incidents[0][1]},controls:[C('incident','Observed incident',incidents.map(x=>x[0])),C('measure','Next measurement',incidents.map(x=>x[1]))],render:s=>{
 const [,expected,evidence]=incidents.find(x=>x[0]===s.incident),match=s.measure===expected;return `<div class="nw-evidence"><small>OBSERVATIONS</small><h3>${s.incident}</h3><p>${evidence}</p></div>`+flow([['Proposed next step',s.measure,'blue'],['Evidence fit',match?'Tests the indicated boundary':'Does not isolate this symptom','purple']])+verdict(match,match?'Useful next measurement':'Revisit where the behavior diverges')+note('This is a hypothesis to investigate. Confirm the mechanism with a targeted measurement, then validate the fix against the same evidence.');
},foot:'Four curated synthetic cases, not automatic diagnosis. Several real failures can produce similar symptoms. No network probes, packet captures, or user data are collected.'});

export const createLab=id=>labs[id]();
export const labIds=()=>Object.keys(labs);
export const mountLab=(element,id)=>mountExperiment(element,createLab(id));
